private static string? Decoration(ZoneDef zone, Terrain terrain, uint hash, int x, int y)
{
    if (zone.Kind == "interior") return null;
    if (zone.Id == "wayfarers_rest" && Math.Abs(x - zone.Spawn.X) < 22 && Math.Abs(y - zone.Spawn.Y) < 22)
